"use client";

import { AnimatePresence, LayoutGroup } from "motion/react";
import { useId, useState } from "react";

import { Button } from "@/components/ui/button";

import { useTimers } from "../auth/shared/use-timers";
import { BlockFrame } from "../parts/block-frame";
import { UserPlusIcon } from "./icons";
import { DIRECTORY, PLAN, SAMPLE_LIST, START_PENDING, START_TEAM, type Suggestion } from "./invite-people/data";
import { PeopleField } from "./invite-people/people-field";
import { SeatPlan } from "./invite-people/seat-plan";
import { TeamStack } from "./invite-people/team-stack";
import type { Chip } from "./shared/email-chip";
import { PendingRow, type PendingRowItem } from "./shared/pending-row";
import { type Role, RoleMenu } from "./shared/role-menu";
import { nameFromEmail } from "./shared/roster";

const VALID = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/**
 * Invites people to the clinic: pick colleagues from the directory or paste
 * a list, see how the seats add up, and send. Each person flies from the
 * suggestion into a chip, into the pending list, and into the team when they join.
 */
export function InvitePeople({ className }: { className?: string }) {
  const titleId = useId();
  const { later } = useTimers();
  const [team, setTeam] = useState<{ email: string; name: string; hue: number }[]>(START_TEAM);
  const [pending, setPending] = useState<PendingRowItem[]>(START_PENDING);
  const [chips, setChips] = useState<Chip[]>([]);
  const [draft, setDraft] = useState("");
  const [role, setRole] = useState<Role>("Practitioner");
  const [shake, setShake] = useState(0);
  const [status, setStatus] = useState("");

  const known = (email: string) => team.some((person) => person.email === email) || pending.some((invite) => invite.email === email);

  const commit = (text: string) => {
    const next = [...chips];
    for (const raw of text.split(/[,;\s]+/)) {
      const email = raw.trim().toLowerCase();
      if (!email || next.some((chip) => chip.email === email) || known(email)) continue;
      const listed = DIRECTORY.find((item) => item.email === email);
      next.push({ email, name: listed?.name ?? nameFromEmail(email), hue: listed?.hue ?? (next.length % 5) + 1, valid: VALID.test(email) });
    }
    setChips(next);
    setDraft("");
  };

  const pick = (item: Suggestion) => {
    setChips((current) => [...current, { email: item.email, name: item.name, hue: item.hue, valid: true }]);
    setDraft("");
  };

  const send = () => {
    const bad = chips.filter((chip) => !chip.valid);
    const over = team.length + pending.length + chips.length - PLAN.seats;
    if (bad.length || over > 0) {
      setShake((value) => value + 1);
      setStatus(bad.length ? `${bad.length} ${bad.length === 1 ? "address is" : "addresses are"} not valid.` : `${over} over the plan.`);
      return;
    }
    if (!chips.length) return;
    const sent = chips.map((chip) => ({ email: chip.email, name: chip.name, hue: chip.hue, role, sent: "Sent just now" }));
    setPending((current) => [...sent, ...current]);
    setChips([]);
    setStatus(`${sent.length} ${sent.length === 1 ? "invite" : "invites"} sent.`);
    // One of the new people accepts a moment later and joins the team.
    const first = sent[0]!;
    later(() => {
      setPending((current) => current.filter((invite) => invite.email !== first.email));
      setTeam((current) => [{ email: first.email, name: first.name, hue: first.hue }, ...current]);
      setStatus(`${first.name} joined Harbour Street.`);
    }, 2600);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <LayoutGroup>
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Invite to Harbour Street
            </h2>
            <p className="text-sm text-muted-foreground">New people get an email and join with the role you pick.</p>
          </div>
          <TeamStack people={team} />
        </header>

        <div className="flex flex-col gap-4 border-b border-border px-5 py-4">
          <PeopleField
            chips={chips}
            draft={draft}
            shake={shake}
            suggestions={DIRECTORY}
            onTeam={known}
            onDraft={setDraft}
            onPick={pick}
            onCommit={commit}
            onRemove={(email) => setChips((current) => current.filter((chip) => chip.email !== email))}
          />
          <p className="-mt-2 text-sm text-muted-foreground">
            Separate addresses with a comma or a new line.{" "}
            <Button variant="link" size="sm" onClick={() => commit(SAMPLE_LIST)}>
              Paste a sample list
            </Button>
          </p>
          <SeatPlan members={team.length} pending={pending.length} adding={chips.length} shake={shake} />
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-1 text-sm text-muted-foreground">
              Invite as
              <RoleMenu label="Role for these invites" value={role} onChange={setRole} />
            </div>
            <div className="flex items-center gap-2">
              <Button variant="outline" disabled={!chips.length && !draft} onClick={() => {
                  setChips([]);
                  setDraft("");
                }}>
                Reset
              </Button>
              <Button onClick={send} disabled={!chips.length}>
                <UserPlusIcon aria-hidden="true" className="size-4" />
                {chips.length ? `Send ${chips.length} ${chips.length === 1 ? "invite" : "invites"}` : "Send invites"}
              </Button>
            </div>
          </div>
        </div>

        <section aria-labelledby={`${titleId}-pending`} className="py-3">
          <h3 id={`${titleId}-pending`} className="px-5 pb-1 text-sm font-medium">
            Pending <span className="text-muted-foreground">{pending.length}</span>
          </h3>
          <ul className="flex flex-col">
            <AnimatePresence initial={false}>
              {pending.map((invite) => (
                <PendingRow
                  key={invite.email}
                  invite={invite}
                  layoutId={`invite-${invite.email}`}
                  onResend={() => {
                    setPending((current) => current.map((item) => (item.email === invite.email ? { ...item, sent: "Sent again just now" } : item)));
                    setStatus(`Invite sent again to ${invite.email}.`);
                  }}
                  onRevoke={() => {
                    setPending((current) => current.filter((item) => item.email !== invite.email));
                    setStatus(`Invite to ${invite.email} removed.`);
                  }}
                />
              ))}
            </AnimatePresence>
          </ul>
          {pending.length === 0 ? <p className="px-5 py-2 text-sm text-muted-foreground">No invites waiting.</p> : null}
        </section>
        <p aria-live="polite" className="sr-only">
          {status}
        </p>
      </LayoutGroup>
    </BlockFrame>
  );
}

