/** A person's initials, at most two letters. */
export const initials = (name: string) =>
  name
    .split(/\s+/)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();

/** Guesses a display name from an email address, such as "dana.reyes@..." to "Dana Reyes". */
export const nameFromEmail = (email: string) =>
  (email.split("@")[0] ?? email)
    .split(/[._-]+/)
    .filter(Boolean)
    .map((part) => part[0]!.toUpperCase() + part.slice(1))
    .join(" ");

"use client";

import { motion } from "motion/react";
import { type KeyboardEvent, useId, useState } from "react";

import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { type Chip, EmailChip } from "../shared/email-chip";
import { PersonAvatar } from "../shared/person-avatar";
import type { Suggestion } from "./data";

/** Props for the people field. `onTeam` says who cannot be picked again. */
export interface PeopleFieldProps {
  chips: Chip[];
  draft: string;
  shake: number;
  suggestions: Suggestion[];
  onTeam: (email: string) => boolean;
  onDraft: (value: string) => void;
  onPick: (suggestion: Suggestion) => void;
  onCommit: (text: string) => void;
  onRemove: (email: string) => void;
}

/**
 * A combobox that takes names or addresses. Arrows move through matching
 * colleagues, skipping people already on the team; Enter adds; comma or
 * semicolon commits typed text; Backspace removes the last chip.
 */
export function PeopleField({ chips, draft, shake, suggestions, onTeam, onDraft, onPick, onCommit, onRemove }: PeopleFieldProps) {
  const id = useId();
  const listId = `${id}-list`;
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const needle = draft.trim().toLowerCase();
  const matches = suggestions.filter((item) => !chips.some((chip) => chip.email === item.email) && (!needle || `${item.name} ${item.email}`.toLowerCase().includes(needle)));
  const pickable = matches.map((item, index) => (onTeam(item.email) ? -1 : index)).filter((index) => index >= 0);
  const showList = open && matches.length > 0;

  const move = (step: number) => {
    if (!pickable.length) return;
    const at = pickable.indexOf(active);
    const next = at < 0 ? (step > 0 ? 0 : pickable.length - 1) : (at + step + pickable.length) % pickable.length;
    setActive(pickable[next]!);
    setOpen(true);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      move(event.key === "ArrowDown" ? 1 : -1);
    } else if (event.key === "Enter") {
      const chosen = matches[active];
      if (showList && chosen && !onTeam(chosen.email)) {
        event.preventDefault();
        onPick(chosen);
        setActive(-1);
      } else if (draft.trim()) {
        event.preventDefault();
        onCommit(draft);
      }
    } else if ((event.key === "," || event.key === ";") && draft.trim()) {
      event.preventDefault();
      onCommit(draft);
    } else if (event.key === "Backspace" && !draft && chips.length) {
      event.preventDefault();
      onRemove(chips[chips.length - 1]!.email);
    } else if (event.key === "Escape" && open) {
      event.preventDefault();
      setOpen(false);
    }
  };

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-medium">
        Name or email
      </label>
      <div className="relative">
        <Input
          id={id}
          role="combobox"
          aria-expanded={showList}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={showList && active >= 0 ? `${listId}-${active}` : undefined}
          autoComplete="off"
          value={draft}
          placeholder="Type a name, or paste addresses"
          onChange={(event) => {
            onDraft(event.target.value);
            setOpen(true);
            setActive(-1);
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => setOpen(false)}
          onKeyDown={onKeyDown}
          onPaste={(event) => {
            const text = event.clipboardData.getData("text");
            if (/[,;\s]/.test(text.trim())) {
              event.preventDefault();
              onCommit(draft + text);
            }
          }}
        />
        <div
          hidden={!showList}
          className="absolute inset-x-0 top-full z-20 mt-1 rounded-lg border border-border bg-popover text-popover-foreground shadow-lg"
        >
          <ul id={listId} role="listbox" aria-label="Colleagues" className="max-h-64 scroll-fade-effect-y scrollbar-none overflow-y-auto p-1">
        {matches.map((item, index) => {
          const member = onTeam(item.email);
          return (
            <li
              key={item.email}
              id={`${listId}-${index}`}
              role="option"
              aria-selected={index === active}
              aria-disabled={member || undefined}
              onMouseDown={(event) => event.preventDefault()}
              onMouseEnter={() => !member && setActive(index)}
              onClick={() => !member && onPick(item)}
              className={cn(
                "flex cursor-pointer items-center gap-3 rounded-md px-2 py-1.5 text-sm",
                index === active && "bg-accent text-accent-foreground",
                member && "cursor-default opacity-50",
              )}
            >
              <motion.span layoutId={member ? undefined : `invite-${item.email}`}>
                <PersonAvatar name={item.name} hue={item.hue} size="sm" />
              </motion.span>
              <span className="min-w-0 flex-1">
                <span className="block truncate">{item.name}</span>
                <span className="block truncate text-xs text-muted-foreground">{member ? "Already on the team" : item.where}</span>
              </span>
            </li>
          );
        })}
          </ul>
        </div>
      </div>
      {chips.length ? (
        <ul aria-label="People to invite" className="flex flex-wrap gap-1.5">
          {chips.map((chip) => (
            <li key={chip.email}>
              <EmailChip chip={chip} layoutId={`invite-${chip.email}`} shake={shake} onRemove={() => onRemove(chip.email)} />
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { XIcon } from "../../parts/icons";
import { PersonAvatar } from "./person-avatar";

/** One address waiting in the invite field. */
export interface Chip {
  email: string;
  name: string;
  hue: number;
  valid: boolean;
}

/** Props for one chip. `shake` changes on each refused send, so a wrong chip shakes again. */
export interface EmailChipProps {
  chip: Chip;
  /** Shared with the row the chip turns into, so it flies there. */
  layoutId: string;
  shake: number;
  onRemove: () => void;
}

/** An address as a removable chip: the avatar and address, red when the address is not valid. */
export function EmailChip({ chip, layoutId, shake, onRemove }: EmailChipProps) {
  const reduce = useReducedMotion();
  const shaking = !chip.valid && shake > 0 && !reduce;

  return (
    <motion.span layoutId={layoutId} layout="position" className="inline-flex">
      <motion.span
        key={shaking ? shake : 0}
        initial={false}
        animate={shaking ? { x: [0, -5, 5, -4, 4, 0] } : { x: 0 }}
        transition={{ duration: 0.36 }}
        className={cn(
          "inline-flex max-w-full items-center gap-1.5 rounded-full border py-0.5 pr-0.5 pl-0.5 text-sm",
          chip.valid ? "border-border" : "border-destructive text-destructive",
        )}
      >
        <PersonAvatar name={chip.name} hue={chip.hue} size="sm" className="scale-75" />
        <span className="max-w-48 truncate">{chip.email}</span>
        {chip.valid ? null : <span className="sr-only">, not a valid address</span>}
        <Button type="button" variant="ghost" size="icon" className="size-6" aria-label={`Remove ${chip.email}`} onClick={onRemove}>
          <XIcon aria-hidden="true" className="size-3" />
        </Button>
      </motion.span>
    </motion.span>
  );
}

import { cn } from "@/lib/utils";

import { initials, type Presence } from "./roster";

const FILLS = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"];
const DOTS = { online: "bg-success", away: "bg-warning", offline: "bg-muted-foreground" } satisfies Record<Presence, string>;
const SIZES = { sm: "size-7 text-xs", md: "size-9 text-sm", lg: "size-20 text-2xl" };

/** Props for a person's avatar. The name sits beside it, so the avatar itself is hidden from screen readers. */
export interface PersonAvatarProps {
  name: string;
  hue: number;
  size?: keyof typeof SIZES;
  presence?: Presence;
  /** Draws a ring in the card colour, for avatars that overlap in a stack. */
  ring?: boolean;
  className?: string;
}

/** A round avatar: the person's initials on one of the five chart hues, with an optional presence dot. */
export function PersonAvatar({ name, hue, size = "md", presence, ring, className }: PersonAvatarProps) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex shrink-0", className)}>
      <span
        className={cn(
          "flex items-center justify-center rounded-full font-semibold text-primary-foreground select-none",
          FILLS[(hue - 1) % 5],
          SIZES[size],
          ring && "ring-2 ring-card",
        )}
      >
        {initials(name)}
      </span>
      {presence ? <span className={cn("absolute right-0 bottom-0 size-2.5 rounded-full ring-2 ring-card", DOTS[presence])} /> : null}
    </span>
  );
}

"use client";

import type { CSSProperties } from "react";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

import { AlertTriangleIcon } from "../../parts/icons";
import { RollingText } from "../../parts/rolling-text";
import { PLAN } from "./data";


/** Props for the seat plan meter. `shake` changes on each refused send. */
export interface SeatPlanProps {
  members: number;
  pending: number;
  adding: number;
  shake: number;
}

const PARTS = [
  { key: "members", label: "Members", fill: "bg-chart-1" },
  { key: "pending", label: "Pending", fill: "bg-chart-4" },
  { key: "adding", label: "New", fill: "bg-chart-2" },
] as const;

/** The plan's seats split into members, pending invites and the people being added, with a notice when they do not fit. */
export function SeatPlan({ members, pending, adding, shake }: SeatPlanProps) {
  const reduce = useReducedMotion();
  const counts = { members, pending, adding };
  const over = members + pending + adding - PLAN.seats;

  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap items-baseline justify-between gap-2 text-sm">
        <span className="font-medium">{PLAN.name}</span>
        <span className="text-muted-foreground">
          <RollingText text={String(members + pending + adding)} className="font-semibold text-foreground" /> of {PLAN.seats} seats
        </span>
      </div>
      <div aria-hidden="true" className="flex h-2 gap-0.5 overflow-hidden rounded-full bg-muted">
        {PARTS.map((part) => (
          // SAFETY: the style holds only the `--fill` custom property, which React passes through untouched.
          <span
            key={part.key}
            className={cn("w-(--fill)", part.fill, "motion-safe:transition-all motion-safe:duration-300")}
            style={{ "--fill": `${(Math.min(counts[part.key], PLAN.seats) / Math.max(PLAN.seats, members + pending + adding)) * 100}%` } as CSSProperties}
          />
        ))}
      </div>
      <dl className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
        {PARTS.map((part) => (
          <div key={part.key} className="flex items-center gap-1.5">
            <span aria-hidden="true" className={cn("size-2 rounded-full", part.fill)} />
            <dt>{part.label}</dt>
            <dd className="font-medium text-foreground tabular-nums">{counts[part.key]}</dd>
          </div>
        ))}
      </dl>
      <div aria-live="polite">
        {over > 0 ? (
          <motion.p
            key={shake}
            initial={false}
            animate={reduce || shake === 0 ? { x: 0 } : { x: [0, -5, 5, -4, 4, 0] }}
            transition={{ duration: 0.36 }}
            className="flex items-center gap-2 text-sm text-destructive"
          >
            <AlertTriangleIcon aria-hidden="true" className="size-4 shrink-0" />
            {over} over the plan. Remove {over === 1 ? "one person" : `${over} people`} or add seats.
          </motion.p>
        ) : null}
      </div>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { motion } from "motion/react";

import { PersonAvatar } from "../shared/person-avatar";

/** Props for the team stack. Each person keeps the layout id they had as a pending row. */
export interface TeamStackProps {
  people: { email: string; name: string; hue: number }[];
  /** How many avatars show before the rest fold into a count. */
  max?: number;
}

/** Overlapping avatars of the team, newest first, with a count for the rest. */
export function TeamStack({ people, max = 5 }: TeamStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <div className="flex items-center" aria-label={`${people.length} people on the team`} role="img">
      {shown.map((person) => (
        <motion.span key={person.email} layoutId={`invite-${person.email}`} className="-ml-2 first:ml-0">
          <PersonAvatar name={person.name} hue={person.hue} size="sm" ring />
        </motion.span>
      ))}
      {rest > 0 ? (
        <span aria-hidden="true" className="-ml-2 flex size-7 items-center justify-center rounded-full bg-muted text-xs font-medium ring-2 ring-card">
          +{rest}
        </span>
      ) : null}
    </div>
  );
}

