"use client";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { ChevronDownIcon } from "../../parts/icons";

/** The roles a clinic member can hold, apart from the owner. */
export const ROLES = ["Admin", "Practitioner", "Front desk", "Read only"] as const;

/** One of `ROLES`. */
export type Role = (typeof ROLES)[number];

/** Props for a role menu. `label` names what the role belongs to, such as a person. */
export interface RoleMenuProps {
  value: Role;
  onChange: (role: Role) => void;
  label: string;
  disabled?: boolean;
}

/** A small menu that shows a role and lets the person pick another. */
export function RoleMenu({ value, onChange, label, disabled }: RoleMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild disabled={disabled}>
        <Button variant="ghost" size="sm" aria-label={`${label}: ${value}. Change role`}>
          {value}
          <ChevronDownIcon aria-hidden="true" className="size-3.5" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuRadioGroup value={value} onValueChange={(next) => {
            const role = ROLES.find((item) => item === next);
            if (role) onChange(role);
          }}>
          {ROLES.map((role) => (
            <DropdownMenuRadioItem key={role} value={role}>
              {role}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
